import{_ as a,o as i,c as s,a5 as t}from"./chunks/framework.C5BPAM3s.js";const u=JSON.parse('{"title":"Waht is PAZ","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/introduction.md","filePath":"docs/introduction.md"}'),l={name:"docs/introduction.md"};function n(r,e,o,c,d,h){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="waht-is-paz" tabindex="-1">Waht is PAZ <a class="header-anchor" href="#waht-is-paz" aria-label="Permalink to “Waht is PAZ”">​</a></h1><p>PAZ is a staticly typed language. It is designed to write robust and explicit software.</p><p>The main purposes are Backend Software (FastCGI API) and scripting (execution from PAZ-CLI)</p><h2 id="influences" tabindex="-1">Influences <a class="header-anchor" href="#influences" aria-label="Permalink to “Influences”">​</a></h2><p>Alpha Script is heavily influence by:</p><h3 id="zig" tabindex="-1">Zig <a class="header-anchor" href="#zig" aria-label="Permalink to “Zig”">​</a></h3><ul><li>Explicitnes</li><li>Error handling</li></ul><h3 id="php" tabindex="-1">Php <a class="header-anchor" href="#php" aria-label="Permalink to “Php”">​</a></h3><ul><li>OOP Features</li><li>PSR</li></ul><h1 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h1><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h2><p>Errors should be resolved as soon as possible but as late as necessary.</p><h2 id="casing" tabindex="-1">Casing <a class="header-anchor" href="#casing" aria-label="Permalink to “Casing”">​</a></h2><p>Types, Classes and Errors in PascalCase</p><p>Varables and Constants in snake_case</p><p>Functions and Methods in cammelCase</p><h2 id="explicit-over-implicit" tabindex="-1">Explicit over implicit <a class="header-anchor" href="#explicit-over-implicit" aria-label="Permalink to “Explicit over implicit”">​</a></h2><h2 id="source-files" tabindex="-1">Source Files <a class="header-anchor" href="#source-files" aria-label="Permalink to “Source Files”">​</a></h2><ul><li>Files must be in UTF8 without BOM.</li><li>Files must use Unit LF (linefeed) lineending only.</li><li>Files should end with an empty line (LF after the last not empty line)</li><li>Lines should not be longer than 80 characters; lines longer than that should be split into multiple subsequent lines of no more than 80 characters each.</li><li>Lines shoudl not contain trailing whitespaces</li><li>Blank lines may be added to improve readability and to indicate related blocks of code</li><li>There should not be more than one statement per line</li></ul><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><p>Modules should declare symbols (Classes, Functions, Constants, Variables, etc.) OR cause side-effects (not both) The phrase &quot;side effects&quot; means execution of logic not directly related to declaring classes, functions, constants, etc.</p>',21)])])}const m=a(l,[["render",n]]);export{u as __pageData,m as default};
